import fs from 'fs';
import path from 'path';

const OFFICIAL_GREEN_BNB_LOGO_BASE64 =
  '';

const BG_COLOR = { r: 1, g: 123, b: 14, alpha: 1 };

async function generateAllIcons() {
  let sharp;
  try {
    const mod = await import('sharp');
    sharp = mod.default || mod;
  } catch (err) {
    const existingLogo = path.resolve(process.cwd(), 'public/logo.png');
    if (fs.existsSync(existingLogo)) {
      console.warn('[Icons] sharp not installed in current runtime; reusing committed icons in public/.');
      const pwa192 = path.resolve(process.cwd(), 'public/pwa-192x192.png');
      const pwa512 = path.resolve(process.cwd(), 'public/pwa-512x512.png');
      if (!fs.existsSync(pwa192)) fs.copyFileSync(existingLogo, pwa192);
      if (!fs.existsSync(pwa512)) fs.copyFileSync(existingLogo, pwa512);
      return;
    }
    throw err;
  }

  const sourceBuffer = Buffer.from(OFFICIAL_GREEN_BNB_LOGO_BASE64, 'base64');

  // 1. Generate 512x512 master PNG buffer
  const master512 = await sharp(sourceBuffer)
    .resize(512, 512, { fit: 'cover', kernel: 'lanczos3' })
    .png({ compressionLevel: 9 })
    .toBuffer();

  // Write Web public icons (Official Green BNB Logo)
  const publicTargets = [
    'public/logo.png',
    'public/bnb_logo.png',
    'public/app_icon.png',
    'public/pwa-512x512.png',
    'android/app/src/main/ic_launcher-web.png',
  ];

  for (const relPath of publicTargets) {
    const fullPath = path.resolve(process.cwd(), relPath);
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    fs.writeFileSync(fullPath, master512);
  }

  // Write 192x192 PWA icon
  await sharp(master512)
    .resize(192, 192, { fit: 'cover', kernel: 'lanczos3' })
    .png({ compressionLevel: 9 })
    .toFile(path.resolve(process.cwd(), 'public/pwa-192x192.png'));

  // Write clean white (#FFFFFF) splash.png across all Android drawable directories so no green/black splash ever appears
  const cleanWhiteSplash = await sharp({
    create: {
      width: 64,
      height: 64,
      channels: 4,
      background: { r: 255, g: 255, b: 255, alpha: 1 },
    },
  })
    .png({ compressionLevel: 9 })
    .toBuffer();

  const splashDirs = [
    'drawable',
    'drawable-port-mdpi',
    'drawable-port-hdpi',
    'drawable-port-xhdpi',
    'drawable-port-xxhdpi',
    'drawable-port-xxxhdpi',
    'drawable-land-mdpi',
    'drawable-land-hdpi',
    'drawable-land-xhdpi',
    'drawable-land-xxhdpi',
    'drawable-land-xxxhdpi',
  ];

  for (const sDir of splashDirs) {
    const targetSplash = path.resolve(process.cwd(), 'android/app/src/main/res', sDir, 'splash.png');
    fs.mkdirSync(path.dirname(targetSplash), { recursive: true });
    fs.writeFileSync(targetSplash, cleanWhiteSplash);
  }

  // Write Apple touch icon & favicons
  await sharp(master512).resize(180, 180, { kernel: 'lanczos3' }).png().toFile(path.resolve(process.cwd(), 'public/apple-touch-icon.png'));
  const fav64 = await sharp(master512).resize(64, 64, { kernel: 'lanczos3' }).png().toBuffer();
  fs.writeFileSync(path.resolve(process.cwd(), 'public/favicon.png'), fav64);
  fs.writeFileSync(path.resolve(process.cwd(), 'public/favicon.ico'), fav64);

  // Replace samity_logo.svg with embedded official green BNB logo so no black SVG remains
  const pngB64 = master512.toString('base64');
  const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">
  <image href="data:image/png;base64,${pngB64}" width="512" height="512" />
</svg>\n`;
  fs.writeFileSync(path.resolve(process.cwd(), 'public/samity_logo.svg'), svgContent, 'utf8');

  // 2. Write Android mipmap icons across all densities
  const densities = [
    { dir: 'mipmap-mdpi', size: 48, fg: 108 },
    { dir: 'mipmap-hdpi', size: 72, fg: 162 },
    { dir: 'mipmap-xhdpi', size: 96, fg: 216 },
    { dir: 'mipmap-xxhdpi', size: 144, fg: 324 },
    { dir: 'mipmap-xxxhdpi', size: 192, fg: 432 },
  ];

  for (const { dir, size, fg } of densities) {
    const outDir = path.resolve(process.cwd(), 'android/app/src/main/res', dir);
    fs.mkdirSync(outDir, { recursive: true });

    // Standard launcher icon
    await sharp(master512)
      .resize(size, size, { fit: 'cover', kernel: 'lanczos3' })
      .png({ compressionLevel: 9 })
      .toFile(path.join(outDir, 'ic_launcher.png'));

    // Round launcher icon (circular mask with inner logo)
    const innerRoundSize = Math.round(size * 0.82);
    const resizedInnerRound = await sharp(master512)
      .resize(innerRoundSize, innerRoundSize, { fit: 'contain', background: BG_COLOR, kernel: 'lanczos3' })
      .png()
      .toBuffer();

    const circleSvg = Buffer.from(
      `<svg width="${size}" height="${size}"><circle cx="${size / 2}" cy="${size / 2}" r="${size / 2}" fill="#017b0e"/></svg>`
    );

    const roundBase = await sharp(circleSvg)
      .composite([{ input: resizedInnerRound, gravity: 'center' }])
      .png()
      .toBuffer();

    const maskSvg = Buffer.from(
      `<svg width="${size}" height="${size}"><circle cx="${size / 2}" cy="${size / 2}" r="${size / 2}" fill="#ffffff"/></svg>`
    );

    await sharp(roundBase)
      .composite([{ input: maskSvg, blend: 'dest-in' }])
      .png({ compressionLevel: 9 })
      .toFile(path.join(outDir, 'ic_launcher_round.png'));

    // Adaptive icon foreground (70% safe zone centered on solid #017b0e background)
    const safeLogoSize = Math.round(fg * 0.70);
    const resizedFgLogo = await sharp(master512)
      .resize(safeLogoSize, safeLogoSize, { fit: 'contain', background: BG_COLOR, kernel: 'lanczos3' })
      .png()
      .toBuffer();

    await sharp({
      create: {
        width: fg,
        height: fg,
        channels: 4,
        background: BG_COLOR,
      },
    })
      .composite([{ input: resizedFgLogo, gravity: 'center' }])
      .png({ compressionLevel: 9 })
      .toFile(path.join(outDir, 'ic_launcher_foreground.png'));
  }

  console.log('Official green BNB icons generated successfully across public/ and android/ mipmap directories.');
}

generateAllIcons().catch((err) => {
  console.error('Error generating official icons:', err);
  process.exit(1);
});
